theorem.raw:
\label{thm:Symmetry_breaking}
    There are boundary data $A_1=-B_1,A_2=B_2>0,\phi_A=-\phi_B$ such that \eqref{eq:DirichletBVP} has
    uncountably many nonsymmetric solutions.

\label{thm:explicit_formula_orbitlike}
     A curve $\gamma:\R\to \Hh$ is an orbitlike elastica parametrized by hyperbolic arclength if and
     only if we have
     \begin{align}
       \gamma_1(s)
       &=\frac{b_1  W_1(s)+b_2 W_2(s)+b_3}{a_1 W_1(s)+a_2 W_2(s)+a_3}, 
       \label{eq:explicit_formula_orbitlike_1}
       \\
       \gamma_2(s)
       &=\frac{1}{\kappa(s)(a_1  W_1(s)+a_2 W_2(s)+a_3)}
       \label{eq:explicit_formula_orbitlike_2}  
     \end{align}
     for $a_1,a_2,a_3,b_1,b_2,b_3\in\R$ such that 
     \begin{equation} \label{eq:a_1a_2a_3b_1b_2b_3}
       a_3= \sqrt{a_1^2+a_2^2}>0,\qquad 
        \vecII{b_1}{b_2} = \frac{b_3}{a_3} \vecII{a_1}{a_2} + \frac{1}{\sqrt{\mu}a_3} \vecII{-a_2}{a_1}.
     \end{equation}
     In this case we moreover have for all $s\in\R$  
     \begin{align} 
       \gamma_2(s)(a_1,a_2)^T&= \xi^1(s) \label{eq:a1a2b1b2_1}, \\ 
       \gamma_2(s) (b_1,b_2)^T &= \gamma_1(s) \xi^1(s)+ \gamma_2(s) \xi^3(s),
       \label{eq:a1a2b1b2_2} \\
       \gamma_1(s) &= \frac{b_3}{a_3} +\frac{1}{2\mu
       a_3}\big(\kappa(s)^2\sin(\phi(s))+2\kappa'(s)\cos(\phi(s))\big), 
       \label{eq:b3a3_1}
       \\
       \gamma_2(s) &= \frac{\kappa(s)}{\mu a_3} 
       + \frac{1}{2\mu a_3}\big(2\kappa'(s)\sin(\phi(s))-\kappa(s)^2\cos(\phi(s))\big).
       \label{eq:b3a3_2}
     \end{align}

\label{thm:explicit_formula_wavelike}
     A curve $\gamma:\R\to \Hh$ is a  wavelike elastica parametrized by hyperbolic arclength if and
     only if we have
     \begin{align} \label{eq:explicit_formula_wavelike}
       \begin{aligned}
       \gamma_1(s)
       &=\frac{b_1  \hat W_1(s)+b_2 \hat W_2(s)+b_3 \kappa(s)}{a_1 \hat W_1(s)+a_2 \hat W_2(s)+a_3\kappa(s)},   \\
       \gamma_2(s)
       &=\frac{1}{a_1 \hat W_1(s)+a_2\hat W_2(s) + a_3\kappa(s)}.
       \end{aligned}
     \end{align}
     for $a_1,a_2,a_3,b_1,b_2,b_3\in\R$ such that 
     \begin{align} \label{eq:wavelike_a_1a_2a_3b_1b_2b_3}
       \begin{aligned}
       &\text{either}\qquad a_3\neq 0, \;\; a_2=\sqrt{a_1^2+a_3^2},\; \;
       \vecII{b_1}{b_2} = \frac{b_3}{a_3} \vecII{a_1}{a_2} - \frac{1}{\sqrt{|\mu|}a_3} \vecII{a_2}{a_1} \\
       &\text{or }\qquad\quad\,
        a_3=0,\;\; a_2=|a_1|,\;\; b_1=\sign(a_1)b_2,\;\; |b_3| =  \frac{1}{\sqrt{|\mu|}}.
        \end{aligned} 
     \end{align}
     In this case the identities \eqref{eq:a1a2b1b2_1},\eqref{eq:a1a2b1b2_2} hold on $\R\sm\{\kappa=0\}$ and for all $s\in\R$ we have
     \begin{align} 
       a_3\gamma_1(s) &= b_3 +\frac{1}{2\mu}\big(\kappa(s)^2\sin(\phi(s))+2\kappa'(s)\cos(\phi(s))\big),  
       \label{eq:wavelike_b3a3_1}  \\
       a_3\gamma_2(s) &= \frac{\kappa(s)}{\mu} 
       + \frac{1}{2\mu}\big(2\kappa'(s)\sin(\phi(s))-\kappa(s)^2\cos(\phi(s))\big).
       \label{eq:wavelike_b3a3_2}
     \end{align}

\label{thm:DirProblemI}
    Let $(A_1,A_2),(B_1,B_2)\in\Hh,\phi_A,\phi_B\in\R$ be given. 
    For $s_*\in\R,k\in (0,1)$ let the functions $\kappa,\vartheta$ be defined by
    \eqref{eq:def_kappa_orbitlike},\eqref{eq:def_theta}. Then the elastica given by
    \eqref{eq:explicit_formula_orbitlike_1},\eqref{eq:explicit_formula_orbitlike_2} solves the Dirichlet
    problem \eqref{eq:DirichletBVP2} if and only if there is an $l\in\Z$ such that
    \begin{align} 
      &a_3 = \frac{2\kappa(0)+2\kappa'(0)\sin(\phi_A)-\kappa(0)^2\cos(\phi_A)}{2\mu A_2}, 
      \label{eq:DirProblem_choice_a3}\\
      &b_3 = a_3 A_1 - \frac{\kappa(0)^2\sin(\phi_A)+2\kappa'(0)\cos(\phi_A)}{2\mu}, 
      \label{eq:DirProblem_choice_b3}  \\



     & a_1+ia_2 = a_3
     \frac{\sigma_2+i\sigma_1}{\sqrt{\sigma_1^2+\sigma_2^2}}e^{i\vartheta(0)}, 
     \label{eq:DirProblem_choice_a1a2}\\


     &b_1+ib_2 = \big( \frac{b_3}{a_3}+\frac{i}{\sqrt\mu a_3}\big)(a_1+ia_2)
     \label{eq:DirProblem_choice_b1b2} \\
     &L= -s_*+\sqrt{2-k^2}\Big( 2lK(k)-\sigma\dn^{-1}\Big(\frac{\sqrt{2-k^2}}{2}\cdot 
         \frac{1+\mu(B_2^2a_3^2+(a_3B_1-b_3)^2)}{2B_2a_3} ,k\Big)\Big)
         \label{Gl:DirProblem_III}
     \intertext{for $\sigma:= \sign\Big(\mu(a_3B_1-b_3)\cos(\phi_B) -\frac{1+\mu(-a_3^2B_2^2+ (a_3B_1-b_3)^2)}{2B_2a_3}
      \sin(\phi_B)\Big)$ and $s_*,k$ satisfy the equations}
      &\Big(\frac{1+\mu(B_2^2a_3^2+(a_3B_1-b_3)^2)}{2B_2a_3}\Big)^2 
      = 2\mu(a_3B_1-b_3)\sin(\phi_B)  \notag \\
     &\hspace{6.2cm} + \frac{1+\mu(-B_2^2a_3^2+ (a_3B_1-b_3)^2)}{B_2a_3}\cos(\phi_B),  
      \label{Gl:DirProblem_I}\\
     &e^{i(\vartheta(L)-\vartheta(0))}
      = \frac{(\sigma_1-i\sigma_2)(\sigma_3+i\sigma_4)}{
       \sqrt{(\sigma_1^2+\sigma_2^2)(\sigma_3^2+\sigma_4^2)}}. \label{Gl:DirProblem_II} 
   \end{align}

lemma.raw:
\label{lem:instability}
      The curve $\gamma_{m,n}$ is unstable provided 
      \begin{align*}
        n > \frac{A(k_{m,n})+\sqrt{A(k_{m,n})^2+4B(k_{m,n})C(k_{m,n})}}{2C(k_{m,n})}
      \end{align*}
      where
      \begin{align*}
        A(k) &:= \frac{\pi\sqrt{5E(k)-(2-k^2)K(k)}}{(2-k^2)K(k)^{3/2}},\\
        B(k) &:=  \frac{\pi^2}{(2-k^2)K(k)^2}, \\
        C(k) &:=  \frac{\sqrt{(16(1-k^2)K(k)^2-44(2-k^2)E(k)K(k)+75E(k)^2)_+}}{\sqrt{3}(2-k^2)K(k)}.
      \end{align*}

proposition.raw:
\label{prop:ode_Z}
    Let $\gamma:\R\to\Hh$ be parametrized by hyperbolic arclength and $Z$ be
    given by \eqref{eq:def_Z}. Then, for all $P\in \C^2$ with $P_2\neq 0$, the function
    $Z(\cdot;P)$ satisfies
    \begin{equation}\label{eq:ODE_Z}
      \kappa Z''-2\kappa'Z'+\kappa(Z+1)\equiv 2\mu C
    \end{equation}
    where $C\in\C$ is, for any $s_0\in\R$,  given by 
     \begin{align} \label{eq:def_C}
       \begin{aligned}
       C &=
       \frac{P_2^2+(\gamma_1(s_0)-P_1)^2}{2P_2\gamma_2(s_0)}\cdot\Big(\frac{\kappa(s_0)}{\mu}+\frac{\kappa'(s_0)}{\mu}\sin(\phi(s_0))
       - \frac{\kappa(s_0)^2}{2\mu}\cos(\phi(s_0))\Big) \\
        & + \frac{\gamma_2(s_0)}{2P_2}\cdot \Big(\frac{\kappa(s_0)}{\mu}-\frac{\kappa'(s_0)}{\mu}\sin(\phi(s_0))
       + \frac{\kappa(s_0)^2}{2\mu}\cos(\phi(s_0))\Big) \\
       &+ \frac{\gamma_1(s_0)-P_1}{P_2}\cdot \Big(
       -\frac{\kappa(s_0)^2}{2\mu}\sin(\phi(s_0))-\frac{\kappa'(s_0)}{\mu}\cos(\phi(s_0)) \Big).
       \end{aligned} 
     \end{align}

\label{prop:properties_vartheta_orbitlike}
    The following identities hold:
    $$
      \vartheta' = \frac{\sqrt\mu \kappa^2}{2(\kappa^2-\mu)},\qquad
       \matII{W_1}{W_2}{W_1'}{W_2'}
      = 
      \matII{0}{\frac{\sqrt{\kappa^2-\mu}}{\kappa}}{\frac{-\sqrt{\mu}\kappa}{2\sqrt{\kappa^2-\mu}}}{
      \frac{\mu\kappa'}{\kappa^2\sqrt{\kappa^2-\mu}}}
      \matII{\cos(\vartheta)}{\sin(\vartheta)}{-\sin(\vartheta)}{\cos(\vartheta)}.
    $$
    Moreover, we have for $s\in\R,l\in\Z$
    \begin{itemize}
	  \item[(i)] $\vartheta(-s_*+l\sqrt{2-k^2}K(k)) = \frac{l-1}{2}\Delta\theta_k$,
      \item[(ii)] $\vartheta(s+2l\sqrt{2-k^2}K(k))-\vartheta(s) = l\Delta\theta_k$,
      \item[(iii)] $\vartheta(-s_*+s)+\vartheta(-s_*-s) = -\Delta\theta_k$.
    \end{itemize}

\label{prop:formula_Z_orbitlike}
     For $P=(P_1,P_2)\in\R^2$ such that $P_2\neq 0$ we have 
     \begin{equation} \label{eq:formula_Z}
       Z(s;P)
       = -1 + \kappa(s)\big( AW_1(s) + BW_2(s) + C\big)
     \end{equation}
     where $C$ is given by \eqref{eq:def_C} and $A,B\in\R$ satisfy  
     \begin{align} \label{eq:formula_AB}
       \vecII{A}{B}
       &= \frac{(\gamma_1(s_0)-P_1)^2+P_2^2}{2\gamma_2(s_0)P_2} \xi^1(s_0)
         + \frac{\gamma_2(s_0)}{2P_2}\xi^2(s_0)
         + \frac{\gamma_1(s_0)-P_1}{P_2}\xi^3(s_0)
         \quad\forall s_0\in\R.
      \end{align}

\label{prop:enclosures}
    We have $\gamma(\R)\subset \overline{B_{R_1}(Q_1)}\sm B_{R_2}(Q_2)$ where
    \begin{align*}
      Q_1 &= \Big( \frac{b_3}{a_3},\frac{\sqrt{2+2\sqrt{1-\mu}}}{\mu a_3}\Big),\qquad
      R_1 = \frac{\sqrt{2-\mu+2\sqrt{1-\mu}}}{\mu a_3}, \\
      Q_2 &= \Big( \frac{b_3}{a_3},\frac{\sqrt{2-2\sqrt{1-\mu}}}{\mu a_3}\Big),\qquad
      R_2 = \frac{\sqrt{2-\mu-2\sqrt{1-\mu}}}{\mu a_3}.
    \end{align*}
    The curve $\gamma$ touches $\partial B_{R_1}(Q_1)$ exactly when $\kappa$ attains its maximum
    and it touches $\partial B_{R_2}(Q_2)$ precisely when $\kappa$ attains its minimum.

\label{prop:rotation}
   The function $k\mapsto \Delta\theta_k$ decreases on $(0,1)$ from its upper limit $\sqrt{2}\pi$ to its lower
   limit $\pi$.

Let $m,n\in \N$ be coprime such that $1<\frac{2m}{n}<\sqrt 2$. Then the closed orbitlike elastica
     $\gamma_{m,n}$ has precisely $n(m-1)$ points of selfintersection characterized by the unique solutions
     $0\leq s<\mathcal{L}_{m,n}$ of the $n(m-1)$ equations
      \begin{equation}\label{eq:selfintersections}
         \frac{\vartheta(s)}{\pi} =\frac{(l-1)m}{n}-p 
      \end{equation} 
      where $l,p\in\Z$ satisfy the following conditions:







      \begin{align} \label{eq:selfintersection_lp_conditions}
        \begin{aligned}
        l\in\{1,\ldots,2n-1\},\qquad
        p\in \big\{1,\ldots, \Big\lceil \frac{\min\{l,2n-l\}m}{n}\Big\rceil -1 \big\}.
        \end{aligned}
      \end{align}

\label{prop:properties_vartheta_wavelike}
    For $W_1,W_2,\vartheta$ as above the following identities hold on $\R\sm\{\kappa=0\}$:
    $$
      \vartheta'
       = \frac{\sqrt{|\mu|} \kappa^2}{2(\kappa^2-\mu)},\quad
       \matII{W_1}{W_2}{W_1'}{W_2'}
      =  
      \matII{0}{\frac{\sqrt{\kappa^2-\mu}}{\kappa}}{-\frac{\sqrt{|\mu|}\kappa}{2\sqrt{\kappa^2-\mu}}}{
      \frac{\mu\kappa'}{\kappa^2\sqrt{\kappa^2-\mu}}}
      \matII{\cosh(\vartheta)}{-\sinh(\vartheta)}{-\sinh(\vartheta)}{\cosh(\vartheta)}.
    $$

\label{prop:formula_Z_wavelike}
     For $P\in\C^2,P_2\neq 0$ we have 
     \begin{equation} \label{eq:formula_Z_wavelike}
       Z(s;P)
       = -1 + A \hat W_1(s) + B\hat W_2(s) + C\kappa(s) 
     \end{equation}
     where $A,B,C\in\C$ are given by \eqref{eq:formula_AB},\eqref{eq:def_C} whenever $\kappa(s_0)\neq 0$.

\label{prop:oscillations_wavelike}
    Assume $a_3\neq 0$. Then we have $\gamma(\R)\subset \overline{B_{R_1}(Q_1)}\sm B_{R_2}(Q_2)$ where
    \begin{align*}
      Q_1 &= \Big(\frac{b_3}{a_3},~~~\frac{\sqrt{2+2\sqrt{1-\mu}}}{|\mu| |a_3|}\Big),\qquad
      R_1 = \frac{\sqrt{2-\mu+2\sqrt{1-\mu}}}{|\mu| |a_3|}, \\
      Q_2 &= \Big( \frac{b_3}{a_3},-\frac{\sqrt{2+2\sqrt{1-\mu}}}{|\mu| |a_3|}\Big),\qquad
      R_2 = \frac{\sqrt{2-\mu+2\sqrt{1-\mu}}}{|\mu| |a_3|}.
    \end{align*}
    The curve $\gamma$ touches $\partial B_{R_1}(Q_1)$ exactly when $\kappa$ attains its maximum
    and it touches $\partial B_{R_2}(Q_2)$ precisely when $\kappa$ attains its minimum. Moreover, we have
    \begin{align} \label{eq:limits_wavelike}
      \begin{aligned}
      \Big\{\lim_{s\to\infty} \gamma(s), \lim_{s\to -\infty} \gamma(s)\Big\}
      &= \partial B_{R_1}(Q_1) \cap \partial B_{R_2}(Q_2) \\ 
      &= \Big\{ \Big(\frac{b_3}{a_3}-\frac{1}{\sqrt{|\mu|} a_3},0\Big), 
      \Big(\frac{b_3}{a_3}+\frac{1}{\sqrt{|\mu|} a_3},0 \Big) \Big\}.
      \end{aligned} 
    \end{align}

proof.raw:
We recall $\mu=\frac{4(1-k^2)}{(2-k^2)^2}$ and hence $k^2=\frac{2}{\mu}+\frac{2\sqrt{1-\mu}}{\mu}$.
    Then, choosing $P=(P_1,P_2)$ as in Proposition \ref{prop:choice_of_P} we obtain the inequalities
    \begin{align*}
      Z(s;P)
      &\leq -1 + \frac{\max \kappa}{\sqrt{\mu}} 
      \stackrel{\eqref{eq:def_kappa_orbitlike}}{=} 
      -1 + \frac{2}{\sqrt{2-k^2}\sqrt\mu}
      = -1 + \frac{\sqrt{2+2\sqrt{1-\mu}}}{\sqrt{\mu}}
      =:-1+\rho_1,   \\
      Z(s;P)
      &\geq -1 + \frac{\min \kappa}{\sqrt{\mu}} 
      \stackrel{\eqref{eq:def_kappa_orbitlike}}{=} 
      -1 + \frac{2\sqrt{1-k^2}}{\sqrt{2-k^2}\sqrt\mu}
      = -1 + \frac{\sqrt{2-2\sqrt{1-\mu}}}{\sqrt{\mu}}
      =: -1+\rho_2.
    \end{align*}
    Hence we deduce $\gamma(\R)\subset \overline{B_{R_1}(Q_1)}\sm B_{R_2}(Q_2)$ for 
    $$
      Q_1:= (P_1,\rho_1 P_2),\quad 
      Q_2:= (P_1,\rho_2 P_2),\quad 
      R_1:= \sqrt{\rho_1^2-1}|P_2|,\quad
      R_2:= \sqrt{\rho_2^2-1}|P_2|,
    $$
    which proves the result.

Let $P=(P_1,P_2)$ be given as in Proposition \ref{prop:choice_of_P_wavelike}. By definition
    of $Z(\cdot;P)$ and $P_2^2=-|P_2|^2$ we find
    $(\gamma_1-P_1)^2+\gamma_2^2-|P_2|^2=2\gamma_2|P_2|\frac{\kappa}{\sqrt{|\mu|}}$ and thus
    \begin{align*}
      (\gamma_1-P_1)^2+(\gamma_2+\rho|P_2|)^2 &\geq |P_2|^2(1+\rho^2), \\
      (\gamma_1-P_1)^2+(\gamma_2-\rho|P_2|)^2 &\leq |P_2|^2(1+\rho^2),\\
      \text{where }\quad
      \rho:= \frac{\max |\kappa|}{\sqrt{|\mu|}}
      &= \frac{2k}{\sqrt{2k^2-1}\sqrt{|\mu|}} = \frac{\sqrt{2+2\sqrt{1-\mu}}}{\sqrt{|\mu|}}.
    \end{align*}
    Here equality holds if and only if $\kappa$ attains its minimum/maximum, respectively. 
    So if we set
    $$
      Q_1:=(P_1,\rho|P_2|),\quad Q_2:=(P_1,-\rho|P_2|),\quad R_1:=R_2:=|P_2|\sqrt{1+\rho^2}
    $$
    then $\gamma(\R)\subset \overline{B_{R_1}(Q_1)}\sm B_{R_2}(Q_2)$, which is the first statement of the
    theorem. From the explicit formulas from Theorem \ref{thm:explicit_formula_wavelike} and
    Proposition~\ref{prop:W1W2_wavelike} we infer $\gamma_2(s) \to  0$ as $s\to \pm\infty$ and 
    \begin{align*}
      \lim_{s\to\pm\infty}
      \gamma_1(s) 
       \stackrel{\eqref{eq:explicit_formula_wavelike}}{=} 
        \lim_{s\to\pm\infty} \frac{b_1 \frac{\hat W_1(s)}{\hat W_2(s)}+b_2+b_3 \frac{\kappa(s)}{\hat W_2(s)}
         }{a_1    \frac{\hat W_1(s)}{\hat W_2(s)}+a_2+a_3 \frac{\kappa(s)}{\hat W_2(s)}} 
         = \frac{\mp b_1 +b_2}{\mp a_1 +a_2} 
       \stackrel{\eqref{eq:wavelike_a_1a_2a_3b_1b_2b_3}}{=} 
         \frac{b_3}{a_3} \pm \frac{1}{\sqrt{|\mu|} a_3}.
    \end{align*}

In a first step we prove that every solution of \eqref{eq:DirichletBVP2} satisfies
    \eqref{eq:DirProblem_choice_a3}--\eqref{Gl:DirProblem_II} for some $l\in\Z$. In the
    second step we show that these conditions indeed provide solutions of the Dirichlet problem. So let
    $\gamma$ be a solution of the Dirichlet problem with angle function $\phi$. By 
    Theorem~\ref{thm:explicit_formula_orbitlike} the formulas
    \eqref{eq:b3a3_1},\eqref{eq:b3a3_2} and  $e^{i\phi(0)}=e^{i\phi_A},e^{i\phi(L)}=e^{i\phi_B}$ yield
    \begin{align*}
      a_3 &= \frac{2\kappa(0)+2\kappa'(0)\sin(\phi_A)-\kappa(0)^2\cos(\phi_A)}{2\mu A_2}, \\
      a_3 &= \frac{2\kappa(L)+2\kappa'(L)\sin(\phi_B)-\kappa(L)^2\cos(\phi_B)}{2\mu B_2}, \\
      b_3 &= a_3 A_1 - \frac{\kappa(0)^2\sin(\phi_A)+2\kappa'(0)\cos(\phi_A)}{2\mu}, \\
      b_3 &= a_3 B_1 - \frac{\kappa(L)^2\sin(\phi_B)+2\kappa'(L)\cos(\phi_B)}{2\mu}.
    \end{align*}
    These equations imply \eqref{eq:DirProblem_choice_a3},\eqref{eq:DirProblem_choice_b3} as well as
    \begin{align}
      \matII{\cos(\phi_A)}{-\sin(\phi_A)}{\sin(\phi_A)}{\cos(\phi_A)}\vecII{\kappa(0)^2}{2\kappa'(0)}
      &= \vecII{2\kappa(0)-2\mu A_2 a_3}{2\mu(a_3A_1-b_3)}, 
      \label{eq:DirProblem_Formula1a}\\
      \matII{\cos(\phi_B)}{-\sin(\phi_B)}{\sin(\phi_B)}{\cos(\phi_B)}\vecII{\kappa(L)^2}{2\kappa'(L)}
      &= \vecII{2\kappa(L)-2\mu B_2 a_3}{2\mu(a_3B_1-b_3)}.
      \label{eq:DirProblem_Formula1b}
    \end{align}
    Taking the modulus on each side and using $\kappa^4+4(\kappa')^2=4(\kappa^2-\mu)$ we find
    that the quadratic term $4\kappa(0)^2,4\kappa(L)^2$ cancels and we get
    \begin{align}
       \kappa(0) &= \frac{1+\mu(a_3^2A_2^2+(a_3A_1-b_3)^2)}{2A_2a_3},
       \label{eq:DirProblem_Formula2a} \\
       \kappa(L) &= \frac{1+\mu(a_3^2B_2^2+(a_3B_1-b_3)^2)}{2B_2a_3}.
       \label{eq:DirProblem_Formula2b}
    \end{align}
    Plugging these formulas into \eqref{eq:DirProblem_Formula1a},\eqref{eq:DirProblem_Formula1b} we 
    may solve for $\kappa(0)^2,2\kappa'(0),\kappa(L)^2,2\kappa'(L)$ and find
    \begin{align}  
       \kappa(0)^2
    	 &= 2\mu(a_3A_1-b_3)\sin(\phi_A)+ \frac{1+\mu(-a_3^2A_2^2+ (a_3A_1-b_3)^2)}{A_2a_3}\cos(\phi_A),   
    	 \label{eq:DirProblem_Formula3a} \\
      \kappa(L)^2
    	 &= 2\mu(a_3B_1-b_3)\sin(\phi_B)+ \frac{1+\mu(-a_3^2B_2^2+ (a_3B_1-b_3)^2)}{B_2a_3}\cos(\phi_B),   
    	 \label{eq:DirProblem_Formula3b}
    	 \\
    	2\kappa'(0)
    	&= 2\mu(a_3A_1-b_3)\cos(\phi_A) -\frac{1+\mu(-a_3^2A_2^2+ (a_3A_1-b_3)^2)}{A_2a_3} \sin(\phi_A),
    	\label{eq:DirProblem_Formula4a} \\	 
    	2\kappa'(L)
    	&= 2\mu(a_3B_1-b_3)\cos(\phi_B) -\frac{1+\mu(-a_3^2B_2^2+ (a_3B_1-b_3)^2)}{B_2a_3} \sin(\phi_B).
    	\label{eq:DirProblem_Formula4b}
    \end{align}
    Since the values for $\kappa(L)^2$ given by
    \eqref{eq:DirProblem_Formula2b},\eqref{eq:DirProblem_Formula3b} have to coincide, we get
    \eqref{Gl:DirProblem_I} as a necessary condition. Moreover, using the explicit formula for $\kappa$ from
    \eqref{eq:DirProblem_W_2W_1} as well as \eqref{eq:DirProblem_Formula2b},\eqref{eq:DirProblem_Formula4b} we
    obtain the formula for the hyperbolic length $L$ from \eqref{Gl:DirProblem_III}.

   \medskip


   It remains to derive
   \eqref{eq:DirProblem_choice_a1a2},\eqref{eq:DirProblem_choice_b1b2},\eqref{Gl:DirProblem_II}. 
   The equation \eqref{eq:DirProblem_choice_b1b2} is a direct consequence of \eqref{eq:a_1a_2a_3b_1b_2b_3}.
   From $\gamma(0)=(A_1,A_2)$ and $\gamma(L)=(B_1,B_2)$ and the explicit formulas for $\gamma_1,\gamma_2$ from
   Theorem~\ref{thm:explicit_formula_orbitlike} and in particular the relation
   $b=\frac{b_3}{a_3}a+\frac{1}{\sqrt\mu a_3}a^\perp$ from \eqref{eq:a_1a_2a_3b_1b_2b_3} imply 
   \begin{align*}
