    \caption{Wavelike elasticae in $\Hh$ }
    \label{Fig:orbitlike_oscillations}
  \end{figure}

\begin{proof}
    In a first step we prove that every solution of \eqref{eq:DirichletBVP2} satisfies
    \eqref{eq:DirProblem_choice_a3}--\eqref{Gl:DirProblem_II} for some $l\in\Z$. In the
    second step we show that these conditions indeed provide solutions of the Dirichlet problem. So let
    $\gamma$ be a solution of the Dirichlet problem with angle function $\phi$. By 
    Theorem~\ref{thm:explicit_formula_orbitlike} the formulas
    \eqref{eq:b3a3_1},\eqref{eq:b3a3_2} and  $e^{i\phi(0)}=e^{i\phi_A},e^{i\phi(L)}=e^{i\phi_B}$ yield
    \begin{align*}
      a_3 &= \frac{2\kappa(0)+2\kappa'(0)\sin(\phi_A)-\kappa(0)^2\cos(\phi_A)}{2\mu A_2}, \\
      a_3 &= \frac{2\kappa(L)+2\kappa'(L)\sin(\phi_B)-\kappa(L)^2\cos(\phi_B)}{2\mu B_2}, \\
      b_3 &= a_3 A_1 - \frac{\kappa(0)^2\sin(\phi_A)+2\kappa'(0)\cos(\phi_A)}{2\mu}, \\
      b_3 &= a_3 B_1 - \frac{\kappa(L)^2\sin(\phi_B)+2\kappa'(L)\cos(\phi_B)}{2\mu}.
    \end{align*}
    These equations imply \eqref{eq:DirProblem_choice_a3},\eqref{eq:DirProblem_choice_b3} as well as
    \begin{align}
      \matII{\cos(\phi_A)}{-\sin(\phi_A)}{\sin(\phi_A)}{\cos(\phi_A)}\vecII{\kappa(0)^2}{2\kappa'(0)}
      &= \vecII{2\kappa(0)-2\mu A_2 a_3}{2\mu(a_3A_1-b_3)}, 
      \label{eq:DirProblem_Formula1a}\\
      \matII{\cos(\phi_B)}{-\sin(\phi_B)}{\sin(\phi_B)}{\cos(\phi_B)}\vecII{\kappa(L)^2}{2\kappa'(L)}
      &= \vecII{2\kappa(L)-2\mu B_2 a_3}{2\mu(a_3B_1-b_3)}.
      \label{eq:DirProblem_Formula1b}
    \end{align}
    Taking the modulus on each side and using $\kappa^4+4(\kappa')^2=4(\kappa^2-\mu)$ we find
    that the quadratic term $4\kappa(0)^2,4\kappa(L)^2$ cancels and we get
    \begin{align}
       \kappa(0) &= \frac{1+\mu(a_3^2A_2^2+(a_3A_1-b_3)^2)}{2A_2a_3},
       \label{eq:DirProblem_Formula2a} \\
       \kappa(L) &= \frac{1+\mu(a_3^2B_2^2+(a_3B_1-b_3)^2)}{2B_2a_3}.
       \label{eq:DirProblem_Formula2b}
    \end{align}
    Plugging these formulas into \eqref{eq:DirProblem_Formula1a},\eqref{eq:DirProblem_Formula1b} we 
    may solve for $\kappa(0)^2,2\kappa'(0),\kappa(L)^2,2\kappa'(L)$ and find
    \begin{align}  
       \kappa(0)^2
    	 &= 2\mu(a_3A_1-b_3)\sin(\phi_A)+ \frac{1+\mu(-a_3^2A_2^2+ (a_3A_1-b_3)^2)}{A_2a_3}\cos(\phi_A),   
    	 \label{eq:DirProblem_Formula3a} \\
      \kappa(L)^2
    	 &= 2\mu(a_3B_1-b_3)\sin(\phi_B)+ \frac{1+\mu(-a_3^2B_2^2+ (a_3B_1-b_3)^2)}{B_2a_3}\cos(\phi_B),   
    	 \label{eq:DirProblem_Formula3b}
    	 \\
    	2\kappa'(0)
    	&= 2\mu(a_3A_1-b_3)\cos(\phi_A) -\frac{1+\mu(-a_3^2A_2^2+ (a_3A_1-b_3)^2)}{A_2a_3} \sin(\phi_A),
    	\label{eq:DirProblem_Formula4a} \\	 
    	2\kappa'(L)
    	&= 2\mu(a_3B_1-b_3)\cos(\phi_B) -\frac{1+\mu(-a_3^2B_2^2+ (a_3B_1-b_3)^2)}{B_2a_3} \sin(\phi_B).
    	\label{eq:DirProblem_Formula4b}
    \end{align}
    Since the values for $\kappa(L)^2$ given by
    \eqref{eq:DirProblem_Formula2b},\eqref{eq:DirProblem_Formula3b} have to coincide, we get
    \eqref{Gl:DirProblem_I} as a necessary condition. Moreover, using the explicit formula for $\kappa$ from
    \eqref{eq:DirProblem_W_2W_1} as well as \eqref{eq:DirProblem_Formula2b},\eqref{eq:DirProblem_Formula4b} we
    obtain the formula for the hyperbolic length $L$ from \eqref{Gl:DirProblem_III}.

   \medskip


   It remains to derive
   \eqref{eq:DirProblem_choice_a1a2},\eqref{eq:DirProblem_choice_b1b2},\eqref{Gl:DirProblem_II}. 
   The equation \eqref{eq:DirProblem_choice_b1b2} is a direct consequence of \eqref{eq:a_1a_2a_3b_1b_2b_3}.
   From $\gamma(0)=(A_1,A_2)$ and $\gamma(L)=(B_1,B_2)$ and the explicit formulas for $\gamma_1,\gamma_2$ from
   Theorem~\ref{thm:explicit_formula_orbitlike} and in particular the relation
   $b=\frac{b_3}{a_3}a+\frac{1}{\sqrt\mu a_3}a^\perp$ from \eqref{eq:a_1a_2a_3b_1b_2b_3} imply 
   \begin{align*}
     \matII{a_1}{a_2}{-a_2}{a_1}\vecII{W_1(0)}{W_2(0)}
     =
     \frac{1}{A_2\kappa(0)}  \vecII{\sigma_1}{\sigma_2}, \qquad
     \matII{a_1}{a_2}{-a_2}{a_1}\vecII{W_1(L)}{W_2(L)}
     = \frac{1}{B_2\kappa(L)}\vecII{\sigma_3}{\sigma_4}.
   \end{align*}
   Notice that we used here $\sigma_1=1-a_3A_2\kappa(0),\sigma_2=1-a_3A_2\kappa(L)$, see
   \eqref{eq:sigmas} and \eqref{eq:DirProblem_Formula2a},\eqref{eq:DirProblem_Formula2b}.
   Using $a_1^2+a_2^2=a_3^2$ from~\eqref{eq:a_1a_2a_3b_1b_2b_3} we may solve this linear problem and arrive at
   \begin{align} \label{eq:DirProblem_equationsforW_1W_2}
	\vecII{W_1(0)}{W_2(0)}
	= \frac{1}{a_3^2A_2\kappa(0)}\vecII{ a_1\sigma_1 - a_2\sigma_2}{ a_2\sigma_1 + a_1\sigma_2},
	\qquad
      \vecII{W_1(L)}{W_2(L)}
      = \frac{1}{a_3^2B_2\kappa(L)}  \vecII{ a_1\sigma_3 - a_2\sigma_4}{ a_2\sigma_3 + a_1\sigma_4}.
    \end{align}






   From \eqref{eq:DirProblem_W_2W_1} and \eqref{eq:DirProblem_equationsforW_1W_2} we get
   \begin{align*}
     e^{i\vartheta(0)}
     =  \frac{a_2\sigma_1+a_1\sigma_2+i(a_2\sigma_2-a_1\sigma_1)}{
     \sqrt{(a_1^2+a_2^2)(\sigma_1^2+\sigma_2^2)}},   \qquad
     e^{i\vartheta(L)}
     =  \frac{a_2\sigma_3+a_1\sigma_4+i(a_2\sigma_4-a_1\sigma_3)}{
     \sqrt{(a_1^2+a_2^2)(\sigma_3^2+\sigma_4^2)}}.   
   \end{align*}
   The first equation and $a_1^2+a_2^2=a_3^2$ imply \eqref{eq:DirProblem_choice_a1a2}. Dividing 
   both equations we finally end up with \eqref{Gl:DirProblem_II}. This finishes the ''only if''-part of our
   statement. 

   \medskip

   Now we assume the conditions \eqref{eq:DirProblem_choice_a3}--\eqref{Gl:DirProblem_II} to hold and
   define $\gamma_1,\gamma_2$ by the formulas
   \eqref{eq:explicit_formula_orbitlike_1},\eqref{eq:explicit_formula_orbitlike_2}. Then, by definition of
   $a_1,a_2,b_1,b_2$, the conditions \eqref{eq:a_1a_2a_3b_1b_2b_3} hold so that $(\gamma_1,\gamma_2)$ is an
   orbitlike elastica by Theorem~\ref{thm:explicit_formula_orbitlike} with angle function $\phi$ 
   that satisfies \eqref{eq:formula_phi}. Exploiting the identities~\eqref{eq:b3a3_1},\eqref{eq:b3a3_2} 
   we have
    \begin{align}\label{eq:sigma12_sq}
      \begin{aligned}
      \sigma_1^2+\sigma_2^2
      &= (1-A_2a_3\kappa(0))^2 + \mu(A_1a_3-b_3)^2 \\
      &=
      \frac{(2\mu-2\kappa(0)^2-2\kappa(0)\kappa'(0)\sin(\phi_A)+\kappa(0)^2\cos(\phi_A))^2}{4\mu^2} \\
      &+ \frac{\mu(\kappa(0)^2\sin(\phi_A)+2\kappa'(0)\cos(\phi_A))^2}{4\mu^2}\\
      &= \frac{(\kappa(0)^2-\mu)(2\kappa(0)+2\kappa'(0)\sin(\phi_A)-\kappa(0)^2\cos(\phi_A))^2}{4\mu^2} \\
      &= (\kappa(0)^2-\mu)A_2^2a_3^2,
      \end{aligned} 
    \end{align}
    where we used once again $4(\kappa')^2=4\kappa^2-\kappa^4-4\mu$. 
    This entails 
    \begin{align}\label{eq:aW(0)}
      \begin{aligned}
      &\;aW(0)+ia^\perp W(0) \\
      &= (W_2(0)-iW_1(0))(a_2+ia_1) \\
      &\stackrel{\eqref{eq:def_theta},\eqref{eq:DirProblem_choice_a1a2}}{=} 
        \frac{\sqrt{\kappa(0)^2-\mu}}{\kappa(0)}e^{i\vartheta(0)}\cdot  a_3
        \frac{\sigma_1+i\sigma_2}{\sqrt{\sigma_1^2+\sigma_2^2}}e^{-i\vartheta(0)}   \\
      &\stackrel{\eqref{eq:sigma12_sq}}{=} \frac{\sigma_1+i\sigma_2}{\kappa(0)A_2}. 
      \end{aligned}
    \end{align}
    From this identity and  
    $\sigma_1=1-a_3A_2\kappa(0),\sigma_2= \sqrt\mu (A_1a_3-b_3)$ we deduce  
    \begin{align*}
       \gamma_2(0)
      &\stackrel{\eqref{eq:explicit_formula_orbitlike_2}}{=} \frac{1}{\kappa(0)(aW(0)+a_3)}
      = \frac{1}{\kappa(0)(\frac{\sigma_1}{\kappa(0)A_2}+a_3)} 
      = A_2, \\
      \gamma_1(0) 
      &\stackrel{\eqref{eq:explicit_formula_orbitlike_1}}{=} \frac{bW(0)+b_3}{aW(0)+a_3} \\ 
      &= A_2\kappa(0)(bW(0)+b_3) \\
      &\stackrel{\eqref{eq:DirProblem_choice_b1b2}}{=} 
        A_2\kappa(0) \Big( \frac{b_3}{a_3} aW(0)+ \frac{1}{\sqrt\mu a_3}
      a^\perp W(0)+b_3\Big) \\
      &\stackrel{\eqref{eq:aW(0)}}{=} \frac{b_3}{a_3} \sigma_1 + \frac{1}{\sqrt\mu a_3} \sigma_2 +
      b_3A_2\kappa(0)  \\
      &= A_1.
    \end{align*}
    The same way we find $\sigma_3^2+\sigma_4^2 = (\kappa(L)^2-\mu)B_2^2a_3^2$ and deduce
    \begin{align*}
      aW(L)+ia^\perp W(L) 
      &= (a_2+ia_1)(W_2(L)-iW_1(L)) \\
      &\stackrel{\eqref{eq:DirProblem_W_2W_1}}{=} (a_2+ia_1)(W_2(0)-iW_1(0))
      \frac{\kappa(0)\sqrt{\kappa(L)^2-\mu}}{\kappa(L)\sqrt{\kappa(0)^2-\mu}} e^{i(\vartheta(L)-\vartheta(0))} \\
      &\stackrel{\eqref{Gl:DirProblem_II}}{=} \big(aW(0)+ia^\perp W(0)\big)
      \frac{\kappa(0)\sqrt{\kappa(L)^2-\mu}}{\sqrt{\kappa(0)^2-\mu}\kappa(L)}
      \frac{(\sigma_1-i\sigma_2)(\sigma_3+i\sigma_4)}{\sqrt{\sigma_1^2+\sigma_2^2}\sqrt{\sigma_3^2+\sigma_4^2}}
      \\
      &\stackrel{\eqref{eq:aW(0)}}{=} 
      \frac{\sqrt{\kappa(L)^2-\mu}(\sigma_1+i\sigma_2)}{A_2\kappa(L)\sqrt{\kappa(0)^2-\mu}}
      \frac{(\sigma_1-i\sigma_2)(\sigma_3+i\sigma_4)}{\sqrt{\sigma_1^2+\sigma_2^2}\sqrt{\sigma_3^2+\sigma_4^2}}
      \\
      &=   \frac{\sqrt{\kappa(L)^2-\mu}}{A_2\kappa(L)\sqrt{\kappa(0)^2-\mu}}
      \frac{\sqrt{\sigma_1^2+\sigma_2^2}(\sigma_3+i\sigma_4)}{\sqrt{\sigma_3^2+\sigma_4^2}}   \\
      &\stackrel{\eqref{eq:sigma12_sq}}{=}   \frac{\sigma_3+i\sigma_4}{B_2\kappa(L)}.
    \end{align*}
    As above we deduce $\gamma_1(L)=B_1,\gamma_2(L)=B_2$ so that it remains to show
    $e^{i\phi(0)}=e^{i\phi_A},e^{i\phi(L)}=e^{i\phi_B}$. To this end we prove the formulas
    \eqref{eq:DirProblem_Formula2a}--\eqref{eq:DirProblem_Formula4b} for $\kappa(0),\ldots,2\kappa'(L)$ from
    the ''only if''-part. First we note that the formula for $\kappa(L)$ from
    \eqref{eq:DirProblem_Formula2b} holds by our definition of $L$ from \eqref{Gl:DirProblem_III}. Then the
    formula for $\kappa(L)^2$ from \eqref{eq:DirProblem_Formula3b} is a direct consequence of assumption
    \eqref{Gl:DirProblem_I} and the formula for $2\kappa'(L)$ from \eqref{eq:DirProblem_Formula4b} follows
    from $\sign(\kappa'(L))=\sigma$ and 
    \begin{align*}
      4\kappa'(L)^2
      &= 4\kappa(L)^2-4\mu -\kappa(L)^4 \\
      &= 4\cdot \frac{1+\mu(B_2^2a_3^2+(a_3B_1-b_3)^2)}{2B_2a_3}-4\mu \\
      &\;-   \Big(2\mu(a_3B_1-b_3)\sin(\phi_B)+ \frac{1+\mu(-a_3^2B_2^2+
        (a_3B_1-b_3)^2)}{B_2a_3}\cos(\phi_B)\Big)^2 \\
      &= 4\Big(\mu(a_3B_1-b_3)\cos(\phi_B)
        -\frac{1+\mu(-a_3^2B_2^2+ (a_3B_1-b_3)^2)}{B_2a_3} \sin(\phi_B)\Big)^2.
    \end{align*}
    The formulas for $\kappa(0),\kappa(0)^2,2\kappa'(0)$ follow from the definition of $a_3,b_3$ and
    $4(\kappa')^2=4\kappa^2-\kappa^4-4\mu$. With these formulas we
    deduce $e^{i\phi(0)}=e^{i\phi_A},e^{i\phi(L)}=e^{i\phi_B}$
    from~\eqref{eq:b3a3_1},\eqref{eq:b3a3_2}, which is all what remained to be shown. 
  \end{proof}

  We remark that the dependency of the equation \eqref{Gl:DirProblem_II} with respect to $l$ can be made
  ''more explicit'' because of $\vartheta(s+2l\sqrt{2-k^2}K(k))=\vartheta(s)+l\Delta\theta_k$ for all
  $s\in\R$, see Proposition~\ref{prop:properties_vartheta_orbitlike}~(ii). In the following corollary we
  apply the above theorem to the symmetric Dirichlet  boundary value problem for positively oriented orbitlike
  elasticae from Theorem~\ref{thm:Symmetry}. We recall that positive orientation refers to the fact that we
  only discuss orbitlike elasticae with positive curvature function.

\begin{proof}
    Let the coefficients $a_1,\ldots,b_3$ and $\sigma,L$ be given as in the theorem so that it remains to
    identify all $s_*\in\R,k\in (0,1),l\in\Z$ such that
    \eqref{Gl:DirProblem_I},\eqref{Gl:DirProblem_II} are satisfied.
    Due to $\sin(\phi_B)=0,\cos(\phi_B)=1$ and
    the formulas for $\kappa(L),\kappa(L)^2$ from
    \eqref{eq:DirProblem_Formula2b},\eqref{eq:DirProblem_Formula3b} the equation \eqref{Gl:DirProblem_I} is
    satisfied for any choice of $s_*,k,l$. For our boundary data we have $\sigma_1=\sigma_3,\sigma_2=\sigma_4=-\sqrt\mu b_3$
    so that equation \eqref{Gl:DirProblem_II} is equivalent to $\vartheta(L)-\vartheta(0)= 2m\pi$ for some
    $m\in\N$. Moreover, the formulas
    \eqref{eq:DirProblem_Formula2a},\eqref{eq:DirProblem_Formula2b},\eqref{eq:DirProblem_Formula4a},\eqref{eq:DirProblem_Formula4b}
    imply $\kappa(0)=\kappa(L),\kappa'(0)=\kappa'(L)$ and thus $L=2n\sqrt{2-k^2}K(k)$ for some $n\in\N$.
    So we deduce from Proposition~\ref{prop:properties_vartheta_orbitlike}~(i)
    $$
      2m\pi = \vartheta(L)-\vartheta(0)=n\Delta\theta_k,\quad
      \text{hence } 1<\frac{2m}{n}<\sqrt 2,\; k=k_{m,n}, L=\mathcal{L}_{m,n}.
    $$
    (In other words, the elastica closes up at $s=L$, see section~\ref{subsec:closed_elasticae}.)
    This yields the above characterization of the solutions. Moreover, as in the previous theorem one 
    checks that these solutions are symmetric if and only if $\kappa$ is symmetric about $s=\frac{L}{2}$,
    which is true precisely when $s_*\in\sqrt{2-k^2}K(k)\Z$. 
    Since this is a countable set of real numbers, we obtain uncountably many
    solutions for any choice $s_*\notin \sqrt{2-k^2}K(k)\Z$, see~Figure~\ref{Fig:Symmetry_breaking}.
  \end{proof}


