       \item[(i)] $w_1$ is odd about 0, $w_2$ is even about 0, $w_2(0)>0>w_1'(0)$, 
       \item[(ii)] $w_1(s)^2+w_2(s)^2=2-k^2 -\dn^2(s,k)$ on $\R$,
       \item[(iii)] $w_1(s)w_1'(s)+w_2(s)w_2'(s) = k^2\dn(s,k)\cn(s,k)\sn(s,k)$ on $\R$,
       \item[(iv)] $w_1'(s)^2+w_2'(s)^2=1-k^2+\dn^4(s,k)$ on $\R$,
       \item[(v)] $w_1(s)w_2'(s)-w_2(s)w_1'(s) = \sqrt{1-k^2}\sqrt{2-k^2}$ on $\R$, 
       \item[(vi)] $(w_1+iw_2)(s+2lK(k))= (w_1+iw_2)(s)e^{il\Delta\theta_k}$ for
       all $s\in\R,l\in\Z$.
       \item[(vii)] $(w_1+iw_2)(-K(k))= e^{i(\pi-\Delta\theta_k)/2}$.
     \end{itemize}

   \medskip


   In the proof we make use of the special functions introduced in section~\ref{sec:Jacobi}.  
   From \cite{Whit_modern_analysis}, p.570--575 we obtain that every solution of $w''+2\dn^2(\cdot,k)w=0$ 
   is a linear combination of the so-called Halphen-Hermite solutions $w_+,w_-:\R\to\C$ (first discovered in
   \cite{Her_extrait,Hal_fonc_ell}) which are given by
    \begin{equation} \label{eq:Hermite_Halphen}
       w_\pm(s) = \frac{H(s\mp i\alpha,k)}{\Theta(s,k)}e^{s\zeta(\pm i\alpha,k)}\quad\text{for }
       \alpha\in\C \text{ s.t.} \dn^2(i\alpha,k)=2-k^2.
   \end{equation}
   Here, the functions $H,\Theta,\zeta:\C\times(0,1)\to\C$ denote Jacobi's eta,
    theta and zeta functions from section~\ref{sec:Jacobi}. 
    By Jacobi's imaginary transformation (see 161.01 in \cite{ByrFri_handbook}) we have  
    $$
      \dn(i\alpha,k)^2 
      = \frac{\dn^2(\alpha,k')}{\cn^2(\alpha,k')}
      \stackrel{\eqref{eq:Jacobi_trigonometric_identities}}{=}
      \frac{1-(k')^2\sn^2(\alpha,k')}{1-\sn^2(\alpha,k')} 
      = 1 + \frac{k^2\sn^2(\alpha,k')}{1-\sn^2(\alpha,k')} \qquad (k':=\sqrt{1-k^2})
    $$
    so that one possible choice is $\alpha=\alpha_k$ where 

    $\sn(\alpha_k,k')=k'$, i.e. $\alpha_k:=F(k',k')$, see \eqref{eq:Jac_Inverse}. 
    From the series representation of these special functions in \eqref{eq:JacobianTheta_series} we deduce 
    $w_-=\bar{w}_+$ so that 141.01 and 1051.02 in \cite{ByrFri_handbook} imply that $\Re(w_\pm)$ is odd and
    $\Im(w_\pm)$ is even. We then define $w_1,w_2:\R\to\R$ through the formula
    \begin{equation}\label{eq:def_w1w2}
      w_1(s)+iw_2(s) := \frac{\sqrt{1-k^2}}{\Im(w_+(0))} w_+(s)
    \end{equation}
    so that (i) holds.

    \medskip

    By Proposition 6 in \cite{Val_Heun} for $m_1=m_2=m_3=0,N=1,m_0=1,s=\frac{1}{2},\sigma=2$ the product of
    the two Hermite-Halphen solutions, i.e. $w_+w_-=|w_+|^2$ and thus $w_1^2+w_2^2$, is a real multiple of
    the function $2-k^2-\dn^2(\cdot,k)$. Hence, \eqref{eq:def_w1w2} and the oddness
    of $w_1$ yield $w_1(0)=0,w_2(0)=\sqrt{1-k^2}$ so that (ii) holds. Differentiating (ii) and
    using \eqref{eq:Jacobi_ODE_1terOrdnung},\eqref{eq:Jacobi_ODE_2terOrdnung}
    we get (iii) and (iv). Part (v) follows from the constancy of the Wronskian and
    $w_1(0)=w_2'(0)=0,w_2(0)=\sqrt{1-k^2},w_1'(0)=-\sqrt{2-k^2}$ by (i),(ii),(iv).










     \medskip

     We now prove (vi) and (vii). Using 1051.04 in \cite{ByrFri_handbook} we get 
     \begin{align*}
       w_+(s+2lK(k))
       &= \frac{H(s+2lK(k)-i\alpha_k,k)}{\Theta(s+2lK(k),k)}e^{(s+2lK(k))\zeta(i\alpha_k,k)} \\
       &= \frac{(-1)^l H(s-i\alpha_k,k)}{\Theta(s,k)}e^{s\zeta(i\alpha_k,k)} e^{2lK(k)\zeta(i\alpha_k,k)}
       \\
       &= w_+(s) e^{l(2K(k)\zeta(i\alpha_k,k)+\pi i)}. 
     \end{align*}
     Using various identities from \cite{ByrFri_handbook} (see below for details) we find
    \begin{align*}
      &\;  K(k)\zeta(i\alpha_k,k) \\
      &= K(k)i\cdot \Big( -\zeta(\alpha_k,k') -  \frac{\pi  \alpha_k}{2K(k)K'(k)}
      +\frac{\sn(\alpha_k,k')\dn(\alpha_k,k')}{\cn(\alpha_k,k')}  \Big)    \\
      &= K(k)i\cdot \Big( - \zeta(\alpha_k,k') - \frac{\pi F(k',k')}{2K(k)K'(k)} 
       + \sqrt{1-k^2}\sqrt{2-k^2}  \Big) \\
     &=    K(k)i\cdot \Big( - E(k',k') + \frac{E(k')}{K(k')}F(k',k') - \frac{\pi F(k',k')}{2K(k)K'(k)} 
       + \sqrt{1-k^2}\sqrt{2-k^2}  \Big)    \\
     &=   i\cdot \Big( - E(k',k')K(k) + \frac{F(k',k')}{K(k')}(E(k')K(k)-\frac{\pi}{2})   +
     \sqrt{1-k^2}\sqrt{2-k^2}K(k)  \Big)    \\
     &=    i\cdot \Big( - E(k',k')K(k) + \frac{F(k',k')}{K(k')}(K(k')(K(k)-E(k)))   +
     \sqrt{1-k^2}\sqrt{2-k^2}K(k)  \Big)   \\
     &=   i\cdot \Big( - (E(k',k')K(k) +  F(k',k')(E(k)-K(k)))   +
     \sqrt{1-k^2}\sqrt{2-k^2}K(k)  \Big)   \\
     &=    i\cdot \Big( - \frac{\pi}{2}\Lambda_0(\arcsin(k'),k)  + \sqrt{1-k^2}\sqrt{2-k^2}K(k) 
     \Big)   \\
     &= i\cdot \frac{1}{2}(\Delta\theta_k-\pi).
   \end{align*}
   In the first equality we used 143.02, in the second we used 
   $\sn(\alpha_k,k')=k'$, in the third 130.02 and  140.01, then 110.10 in the fifth and
    150.03 in the seventh and the eigth equality results from the definition of $\Delta\theta_k$,
    see~\eqref{eq:def_rotation}. This proves (vi). 
    Finally, we have
    \begin{align*}
      (w_1+iw_2)(-K(k)) 
      \stackrel{\eqref{eq:Hermite_Halphen}}{=} 
        e^{-K(k)\zeta(i\alpha_k,k)} 

      =  e^{i(\pi-\Delta\theta_k)/2} 
    \end{align*}  
    because of $(w_1^2+w_2^2)(-K(k))=1$ by Proposition~\ref{prop:w1w2_orbitlike}~(ii) and because 
    $H(-K(k)-i\alpha_k,k)$, $\Theta(-K(k),k)$ are real and positive for all $k\in (0,1)$ by
    \eqref{eq:JacobianTheta_series}.   \hfill $\Box$

   \medskip


   Next we prove Proposition~\ref{prop:W1W2_orbitlike}, i.e. that the functions $W_1,W_2$ given by 
   $$
     W_j(s)= \frac{1}{\sqrt{2-k^2}} w_j(-K(k)+\frac{s+s_*}{\sqrt{2-k^2}}) \quad (j=1,2)
   $$
   satisfy the following identities:
   \begin{itemize}
       \item[(i)] $W_1^2+W_2^2 = \frac{\kappa^2-\mu}{\kappa^2}$,
       \item[(ii)] $W_1'= \frac{\mu \kappa'}{\kappa(\kappa^2-\mu)} W_1
      - \frac{\sqrt\mu \kappa^2}{2(\kappa^2-\mu)}W_2 $,
       \item[(iii)] $W_2' = \frac{\sqrt\mu \kappa^2}{2(\kappa^2-\mu)}W_1 + \frac{\mu
       \kappa'}{\kappa(\kappa^2-\mu)} W_2$,



       \item[(iv)] $W_1W_2'-W_2W_1' = \frac{\sqrt\mu}{2}$,
       \item[(v)] $(W_1+iW_2)(s+2l\sqrt{2-k^2}K(k))=(W_1+iW_2)(s)e^{il\Delta\theta_k}$ for $s\in\R,l\in\Z$,
       \item[(vi)] $(W_1+iW_2)(s)= (-W_1+iW_2)(-s-2s_*+2l\sqrt{2-k^2}K(k)) e^{i(l-1)\Delta\theta_k}$
       for $s\in\R,l\in\Z$.
  \end{itemize}

  \medskip


   For the proof we set $z:=-K(k)+ \frac{s+s_*}{\sqrt{2-k^2}}$ so that
      \eqref{eq:def_kappa_orbitlike},\eqref{eq:def_Wj} give
     \begin{align} \label{eq:formulas_z_vs_s}
       \begin{aligned}
       w_j(z)= \sqrt{2-k^2}W_j(s),&\quad w_j'(z)= (2-k^2)W_j'(s) \quad (j=1,2)\\
       \kappa(s) &= \frac{2}{\sqrt{2-k^2}}\dn(z+K(k),k),\\
       \kappa'(s) &= -\frac{2k^2}{2-k^2}\sn(z+K(k),k)\cn(z+K(k),k).
       \end{aligned}
     \end{align}
     Using the identities from \eqref{eq:Jac_Additionstheoreme} we get
     \begin{align} \label{eq:formulas_dnsncn}
       \begin{aligned}
       \dn(z,k)
       &= \frac{\sqrt{1-k^2}}{\dn(z+K(k),k)}
       \stackrel{\eqref{eq:formulas_z_vs_s}}{=}  \frac{2\sqrt{1-k^2}}{\sqrt{2-k^2}} \frac{1}{\kappa(s)}, \\
       \sn(z,k)\cn(z,k)
       &= -  \frac{\sqrt{1-k^2} \sn(z+K(k),k)\cn(z+K(k),k)}{\dn^2(z+K(k),k)}
       \stackrel{\eqref{eq:formulas_z_vs_s}}{=} \frac{2\sqrt{1-k^2}}{k^2} \frac{\kappa'(s)}{\kappa(s)^2}.
       \end{aligned}
     \end{align}
     In particular, using that $w_1,w_2$ are linearly independent by Proposition~\ref{prop:W1W2_orbitlike} (i)
     as well as
     \begin{align*}
       W_j''(s)
       = \frac{1}{(2-k^2)^{3/2}}w_j''(z)
       = - \frac{2}{(2-k^2)^{3/2}} \dn^2(z,k) w_j(z)
       \stackrel{\eqref{eq:formulas_dnsncn}}{=} - 2\mu\kappa(s)^{-2} W_j(s)
       \quad\text{for $j=1,2$},
     \end{align*}
     we get that $\{W_1,W_2\}$ is a fundamental system of the given ODE.
     Now we exploit \eqref{eq:formulas_z_vs_s},\eqref{eq:formulas_dnsncn} and
     Proposition~\ref{prop:w1w2_orbitlike} in order to prove (i)-(vi).
     The first item follows from 
     \begin{align*}
       W_1(s)^2+W_2(s)^2
       &\stackrel{\eqref{eq:formulas_z_vs_s}}{=} \frac{w_1(z)^2+w_2(z)^2}{2-k^2}
       \stackrel{\ref{prop:w1w2_orbitlike}.(ii)}{=} 1-\frac{\dn^2(z,k)}{2-k^2}

       \stackrel{\eqref{eq:formulas_dnsncn}}{=}
       \frac{\kappa(s)^2-\mu}{\kappa(s)^2}. \\
     \intertext{The assertion (ii) is true because of}
       W_1'(s)
       &\stackrel{\eqref{eq:formulas_z_vs_s}}{=} \frac{1}{2-k^2} w_1'(z) \\
       &= \frac{1}{2-k^2}
       \frac{w_1(z)(w_1w_1'+w_2w_2')(z)-w_2(z)(w_1w_2'-w_2w_1')(z)}{(w_1^2+w_2^2)(z)} \\
       &\hspace{-1.2cm}\stackrel{\ref{prop:w1w2_orbitlike}.(ii)-(iv)}{=} \frac{1}{(2-k^2)^{3/2}}
         \frac{k^2\dn(z,k)\cn(z,k)\sn(z,k) W_1(s)- \sqrt{1-k^2}\sqrt{2-k^2}W_2(s)}{W_1(s)^2+W_2(s)^2}
         \\
      &\stackrel{\eqref{eq:formulas_dnsncn}}{=}\frac{4(1-k^2)}{(2-k^2)^2} \frac{\kappa'(s)}{\kappa(s)^3}
      \frac{W_1(s)}{W_1(s)^2+W_2(s)^2} - \frac{\sqrt{1-k^2}}{2-k^2} \frac{W_2(s)}{W_1(s)^2+W_2(s)^2}  \\
      &\stackrel{\ref{prop:W1W2_orbitlike}.(i)}{=} \frac{\mu\kappa'(s)}{\kappa(s)(\kappa(s)^2-\mu)} W_1(s)
      - \frac{\sqrt\mu \kappa(s)^2}{2(\kappa(s)^2-\mu)}W_2(s). \\
     \intertext{Similarly, (iii) follows from}
       W_2'(s)
       &= \frac{1}{2-k^2}
       \frac{w_2(z)(w_1w_1'+w_2w_2')(z)+w_1(z)(w_1w_2'-w_2w_1')(z)}{(w_1^2+w_2^2)(z)} \\
       &= \frac{\sqrt\mu \kappa(s)^2}{2(\kappa(s)^2-\mu)}W_1(s) +
       \frac{\mu\kappa'(s)}{\kappa(s)(\kappa(s)^2-\mu)} W_2(s). \\
     \intertext{









     The items (iv),(v) follow directly from
     Proposition~\ref{prop:w1w2_orbitlike}~(iv),(v).
     Finally, we set $t:= -s-2s_*+2l\sqrt{2-k^2}K(k)$ so that (vi) results from}
     W_1(s)+iW_2(s)
     &= (w_1+iw_2) \big( -K(k)+\frac{-(t+s_*)+2l\sqrt{2-k^2}K(k)}{\sqrt{2-k^2}} \big) \\
     &= (w_1+iw_2) \big( K(k)-\frac{t+s_*}{\sqrt{2-k^2}} + (2l-2)K(k)\big) \\
     &\stackrel{\ref{prop:w1w2_orbitlike}.(vi)}{=}  (w_1+iw_2)
     \big(K(k)-\frac{t+s_*}{\sqrt{2-k^2}}\big) e^{i(l-1)\Delta\theta_k}  \\
     &\stackrel{\ref{prop:w1w2_orbitlike}.(i)}{=} (-w_1+iw_2) \big(-K(k)+\frac{t+s_*}{\sqrt{2-k^2}}\big)
     e^{i(l-1)\Delta\theta_k}  \\
     &= (-W_1(t)+iW_2(t))  e^{i(l-1)\Delta\theta_k}.
   \end{align*} 
   \hfill $\Box$



  Next we prove the assertions from Proposition~\ref{prop:properties_vartheta_orbitlike}, namely  
    $$
      \vartheta' = \frac{\sqrt\mu \kappa^2}{2(\kappa^2-\mu)},\qquad
       \matII{W_1}{W_2}{W_1'}{W_2'}
      =  
      \matII{0}{\frac{\sqrt{\kappa^2-\mu}}{\kappa}}{\frac{-\sqrt{\mu}\kappa}{2\sqrt{\kappa^2-\mu}}}{
      \frac{\mu\kappa'}{\kappa^2\sqrt{\kappa^2-\mu}}}
      \matII{\cos(\vartheta)}{\sin(\vartheta)}{-\sin(\vartheta)}{\cos(\vartheta)}
    $$
    as well as 
    \begin{itemize}
	  \item[(i)] $\vartheta(-s_*+l\sqrt{2-k^2}K(k)) = \frac{l-1}{2}\Delta\theta_k$,
      \item[(ii)] $\vartheta(s+2l\sqrt{2-k^2}K(k))-\vartheta(s) = l\Delta\theta_k$,
      \item[(iii)] $\vartheta(-s_*+s)+\vartheta(-s_*-s) = -\Delta\theta_k$.
    \end{itemize}
   To this end we set $c(s):= \frac{\sqrt{\kappa(s)^2-\mu}}{\kappa(s)}$ so that
   the defining equation for $\vartheta$ \eqref{eq:def_theta} reads
   $$
      \vecII{W_1(s)}{W_2(s)} = c(s) \vecII{-\sin(\vartheta(s))}{\cos(\vartheta(s))}.
    $$
    Differentiating both sides and using Proposition~\ref{prop:W1W2_orbitlike}~(ii),(iii) we arrive at
    \begin{align*}
      &-c(s)\vartheta'(s) \vecII{\cos(\vartheta(s))}{\sin(\vartheta(s))}
      + c'(s) \vecII{-\sin(\vartheta(s))}{\cos(\vartheta(s))} \quad
      =\quad \vecII{W_1'(s)}{W_2'(s)} \\
      &= \frac{\mu\kappa'(s)}{\kappa(s)(\kappa(s)^2-\mu)} \vecII{W_1(s)}{W_2(s)}
      + \frac{\sqrt\mu\kappa(s)^2}{2(\kappa(s)^2-\mu)} \vecII{-W_2(s)}{W_1(s)}   \\
      &= \frac{\mu\kappa'(s)c(s)}{\kappa(s)(\kappa(s)^2-\mu)} \vecII{-\sin(\vartheta(s))}{\cos(\vartheta(s))}
      - \frac{\sqrt\mu\kappa(s)^2c(s)}{2(\kappa(s)^2-\mu)} \vecII{\cos(\vartheta(s))}{\sin(\vartheta(s))}.
    \end{align*}
    This identity gives
    $$
      \vartheta'(s) = \frac{\sqrt{\mu}\kappa(s)^2}{2(\kappa(s)^2-\mu)},\qquad
      c'(s)
      = \frac{\mu\kappa'(s)}{\kappa(s)(\kappa(s)^2-\mu)}c(s)
      =  \frac{\mu\kappa'(s)}{\kappa(s)^2\sqrt{\kappa(s)^2-\mu}} 
    $$
    and thus the first claim follows from
    \begin{align*}
      \matII{W_1(s)}{W_2(s)}{W_1'(s)}{W_2'(s)}
      &=
      \matII{0}{c(s)}{-c(s)\vartheta'(s)}{c'(s)}
      \matII{\cos(\vartheta(s))}{\sin(\vartheta(s))}{-\sin(\vartheta(s))}{\cos(\vartheta(s))}.




    \end{align*}
    Now we prove (i),(ii),(iii). For $l\in\Z$ we have
    \begin{align*}
       \vartheta(-s_*+ l\sqrt{2-k^2}K(k))-\vartheta(-s_*)
       &= \int_{-s_*}^{-s_*+l\sqrt{2-k^2}K(k)} \vartheta'(s) \,ds\\
       &= \int_{-s_*}^{-s_*+l\sqrt{2-k^2}K(k)} \frac{\sqrt{\mu}\kappa(s)^2}{2(\kappa(s)^2-\mu)} \,ds \\
       &= \int_0^{lK(k)}
       \frac{\sqrt{2-k^2}\sqrt{\mu}  \kappa(\sqrt{2-k^2}s-s_*)^2}{2(\kappa(\sqrt{2-k^2}s-s_*)^2-\mu)} \,ds
       \\
       &\stackrel{\eqref{eq:def_kappa_orbitlike}}{=}  \int_0^{lK(k)}
       \frac{\sqrt{1-k^2}\sqrt{2-k^2}\dn(s,k)^2}{(2-k^2)\dn(s,k)^2-1+k^2} \,ds   \\
       &=  \sqrt{1-k^2}\sqrt{2-k^2} \int_0^{lK(k)}
       \frac{\dn(s,k)^2}{(2-k^2)\dn(s,k)^2-1+k^2} \,ds   \\
       &= \frac{l}{2}\cdot 2\sqrt{2-k^2}\sqrt{1-k^2} \int_0^{K(k)}
       \frac{\dn(s,k)^2}{1-k^2(2-k^2)\sn(s,k)^2} \,ds.
     \end{align*}
     Here we used $\dn^2=1-k^2\sn^2$ and $\dn(2K(k)-s,k)=\dn(2K(k)+s,k)=\dn(s,k)$ in the last equation, 
     see~\eqref{eq:Jacobi_trigonometric_identities}. The proof of (i) is finished once we have proved that 
     the second factor equals $\Delta\theta_k$. Using the formula 412.04 from \cite{ByrFri_handbook} for
     $\alpha:=k\sqrt{2-k^2}>k$ we get
     \begin{align*}
       &\;2\sqrt{2-k^2}\sqrt{1-k^2} \int_0^{K(k)}
       \frac{ \dn(s,k)^2}{1-k^2(2-k^2)\sn(s,k)^2} \,ds \\
       &= 2\sqrt{2-k^2}\sqrt{1-k^2} \Big(  K(k) +
       \frac{\pi   \sqrt{\alpha^2-k^2}
       (1-\Lambda_0(\arcsin(\sqrt{(1-\alpha^2)(k')^{-2}}),k))}{2\alpha\sqrt{1-\alpha^2}} \Big)  \\
       &= 2\sqrt{2-k^2}\sqrt{1-k^2} \Big(
       K(k) + \frac{\pi(1-\Lambda_0(\arcsin(k'),k)) }{2\sqrt{1-k^2}\sqrt{2-k^2}} \Big)  \\
       &\stackrel{\eqref{eq:def_rotation}}{=} \Delta\theta_k.
     \end{align*}
     So (i) is proved  once we have shown $\vartheta(-s_*)=-\Delta\theta_k/2$. This identity, however, follows
     from $-2\pi<\vartheta(-s_*)\leq 0$ and 
     \begin{align*}
       e^{i\vartheta(-s_*)}
       \stackrel{\eqref{eq:def_theta}}{=} \frac{(W_2-iW_1)(-s_*)}{\sqrt{2-k^2}}
       \stackrel{\eqref{eq:def_Wj}}{=} (w_2-iw_1)(-K(k))
       = -i(w_1+iw_2)(-K(k))
       \stackrel{\ref{prop:w1w2_orbitlike}.(vii)}{=} e^{- i\Delta\theta_k /2}.
     \end{align*}
     Item (ii) holds thanks to the $2\sqrt{2-k^2}K(k)-$periodicity of $\vartheta'$ and (i), namely
     $$
        \vartheta(s+ 2l\sqrt{2-k^2}K(k))-\vartheta(s)
       = \int_{s}^{s+2l\sqrt{2-k^2}K(k)} \vartheta'(z) \,dz\\
       = \int_{-s_*}^{-s_*+2l\sqrt{2-k^2}K(k)}  \vartheta'(z) \,dz 
       = l\Delta\theta_k
     $$
     Finally, $\vartheta'(-s_*+s)=\vartheta'(-s_*-s)$ and $2\vartheta(-s_*)=-\Delta\theta_k$ imply~(iii).  
     \hfill $\Box$

and
    Proposition~\ref{prop:properties_vartheta_wavelike}}  \label{subsec:proof_propositions_wavelike}

















    We first show  that for all $k\in (0,1)$ the ordinary differential equation $w''-
    \frac{2(1-k^2)}{\cn^2(s,k)}w=0$ has a fundamental system $\{w_1,w_2\}$ on $(-K(k),K(k))$ such that
     \begin{itemize}
       \item[(i)] $w_1$ is odd about 0, $w_2$ is even about 0, $w_2(0)>0>w_1'(0)$,
       \item[(ii)] $\cn^2(s,k)(w_2(s)^2 - w_1(s)^2) = 1-k^2+(2k^2-1)\cn^2(s,k)$ on $(-K(k),K(k))$,
       \item[(iii)] $\cn^3(s,k)(w_2(s)w_2'(s) - w_1(s)w_1'(s)) = (1-k^2)\sn(s,k)\dn(s,k)$ on $(-K(k),K(k))$,


       \item[(iv)] $w_2(s)w_1'(s)-w_1(s)w_2'(s)= -k\sqrt{(1-k^2)(2k^2-1)}$ on $(-K(k),K(k))$, 
        \item[(v)] The functions $\cn(\cdot,k)w_1,\cn(\cdot,k)w_2$ have unique smooth extensions $\hat
       w_1,\hat w_2:\R\to\R$ such that the functions $w_1:=\frac{\hat
       w_1}{\cn(\cdot,k)},w_2:=\frac{\hat w_2}{\cn(\cdot,k)}$ build a fundamental system on
       each connected component of $\R\sm\{\kappa=0\}$. Moreover, $\hat w_2$ is positive on $\R$, $s\hat
       w_1(s)$ is negative on $\R\sm\{0\}$ and, as $s\to\pm\infty$, we have $\hat w_1(s)\to \mp\infty,\hat
       w_2(s)\to\infty$ exponentially and $\hat w_1(s)/\hat w_2(s)\to \mp 1$. 
     \end{itemize}

   \medskip

   The proof is similar to the orbitlike case. We define
   $$
    	w_\pm (s) 
    	:= \frac{\Theta_1(s\pm\alpha_k,k)}{\Theta(s,k)} e^{\mp s\zeta(\alpha_k,k)} 
    	\quad\text{where }\dn^2(\alpha_k,k)=k^2, \text{ i.e. }\alpha_k:= F(k'/k,k)
   $$
     for $\Theta,\Theta_1,\zeta$ as in section~\ref{sec:Jacobi}.
     Notice that $k\in (\frac{1}{\sqrt 2},1)$ implies $k'/k\in (0,1)$ and thus $\alpha_k$ is real. 
     From Proposition~6 in \cite{Val_Heun} (for
     parameters $m_1=0,m_2=1,m_3=0,m_0=0,A=2k^2,s=\frac{2k^2-1}{4},\sigma=2k^2-1$) we infer that  
	 \begin{equation}\label{eq:defn_w1w2_wavelike}
	    w_1(s):= \frac{k(w_+(s) - w_-(s))}{(w_+(0)+w_-(0))\cn(s,k)},\qquad 
	    w_2(s):= \frac{k(w_+(s) + w_-(s))}{(w_+(0)+w_-(0))\cn(s,k)}
	 \end{equation}
      is a fundamental system of the ODE on each connected component of $\R\sm \{\cn(\cdot,k)=0\}$, which
      satisfies (i) thanks to $w_\pm(-s)=w_\mp(s)$.
      The same proposition tells us that the product $w_+w_-$ is a real multiple of the function $1-k^2+(2k^2-1)\cn^2(\cdot,k)$ so that our choice for
      $w_1,w_2$ yields (ii). Differentiating this identity gives (iii) and (iv). Item (v) follows
      from the constancy of the Wronskian and $w_2(0)w_1'(0)-w_1(0)w_2'(0)= -k
      \sqrt{(1-k^2)(2k^2-1)}$. Finally, \eqref{eq:defn_w1w2_wavelike} shows
      that property (v) holds for the choice

      \begin{align*}
        \hat w_1(s)
        &:=  \frac{k(w_+(s) - w_-(s))}{w_+(0)+w_-(0)}
        =\frac{k(\Theta_1(s+\alpha_k,k)e^{-s\zeta(\alpha_k,k)}
        - \Theta_1(s-\alpha_k,k)e^{s\zeta(\alpha_k,k)}}{ 
        (w_+(0)+w_-(0))\Theta(s,k)}, \\
        \hat w_2(s)
        &:= \frac{k(w_+(s) + w_-(s))}{w_+(0)+w_-(0)}
        = \frac{k(\Theta_1(s+\alpha_k,k)e^{-s\zeta(\alpha_k,k)}
        + \Theta_1(s-\alpha_k,k)e^{s\zeta(\alpha_k,k)}}{ 
        (w_+(0)+w_-(0))\Theta(s,k)},
      \end{align*}
      since $\zeta(\alpha_k,k)>0$ and $\Theta_1(\cdot,k),\Theta(\cdot,k)$ are positive periodic functions.
      Notice that the all complex zeros of $\Theta_1,\Theta$ are known to be non-real, see 1051.07 in
      \cite{ByrFri_handbook}. 
      \hfill $\Box$

     \medskip

    Now we prove Proposition~\ref{prop:properties_vartheta_wavelike}. For $W_1,W_2,\vartheta$ as in
   \eqref{eq:def_Wj_wavelike},\eqref{eq:def_theta_wavelike} we have to prove that the following identities
   hold on $\R\sm\{\kappa=0\}$:
    $$
      \vartheta'
       = \frac{\sqrt{|\mu|} \kappa^2}{2(\kappa^2-\mu)},\quad
       \matII{W_1}{W_2}{W_1'}{W_2'}
      =  
      \matII{0}{\frac{\sqrt{\kappa^2-\mu}}{\kappa}}{-\frac{\sqrt{|\mu|}\kappa}{2\sqrt{\kappa^2-\mu}}}{
      \frac{\mu\kappa'}{\kappa^2\sqrt{\kappa^2-\mu}}}
      \matII{\cosh(\vartheta)}{-\sinh(\vartheta)}{-\sinh(\vartheta)}{\cosh(\vartheta)}.
    $$

    \medskip

    We proceed as in the orbitlike case. With $c(s):=
    \frac{\sqrt{\kappa(s)^2-\mu}}{\kappa(s)}$ we may write 
    $$
      \vecII{W_1(s)}{W_2(s)} = c(s) \vecII{-\sinh(\vartheta(s))}{\cosh(\vartheta(s))}.
    $$
    Differentiating both sides and using Proposition~\ref{prop:W1W2_wavelike}~(ii),(iii) we arrive at
    \begin{align*}
      &-c(s)\vartheta'(s) \vecII{\cosh(\vartheta(s))}{-\sinh(\vartheta(s))}
      + c'(s) \vecII{-\sinh(\vartheta(s))}{\cosh(\vartheta(s))} \;
      =\; \vecII{W_1'(s)}{W_2'(s)} \\
      &= \frac{\mu\kappa'(s)}{\kappa(s)(\kappa(s)^2-\mu)} \vecII{W_1(s)}{W_2(s)}
      - \frac{\sqrt{|\mu|}\kappa(s)^2}{2(\kappa(s)^2-\mu)} \vecII{W_2(s)}{W_1(s)}   \\
      &= \frac{\mu\kappa'(s)c(s)}{\kappa(s)(\kappa(s)^2-\mu)}
      \vecII{-\sinh(\vartheta(s))}{\cosh(\vartheta(s))} 
      - \frac{\sqrt{|\mu|}\kappa(s)^2c(s)}{2(\kappa(s)^2-\mu)}
      \vecII{\cosh(\vartheta(s))}{-\sinh(\vartheta(s))}.
    \end{align*}
    This identity gives
    $$
      \vartheta'(s) = \frac{\sqrt{|\mu|}\kappa(s)^2}{2(\kappa(s)^2-\mu)},\qquad
      c'(s)
      = \frac{\mu\kappa'(s)c(s)}{\kappa(s)(\kappa(s)^2-\mu)} 
      =  \frac{\mu\kappa'(s)}{\kappa(s)^2\sqrt{\kappa(s)^2-\mu}}
    $$
    and the claim follows from
    \begin{align*}
      \matII{W_1}{W_2}{W_1'}{W_2'}
      &= 
       \matII{0}{c}{-c\vartheta'}{c'}\matII{\cosh(\vartheta)}{
       -\sinh(\vartheta)}{-\sinh(\vartheta)}{\cosh(\vartheta)}.
    \end{align*}
    \hfill $\Box$

Following the reasoning from the beginning of this section this leads to the following result:

  \begin{prop}\label{prop:enclosures}
    We have $\gamma(\R)\subset \overline{B_{R_1}(Q_1)}\sm B_{R_2}(Q_2)$ where
    \begin{align*}
      Q_1 &= \Big( \frac{b_3}{a_3},\frac{\sqrt{2+2\sqrt{1-\mu}}}{\mu a_3}\Big),\qquad
      R_1 = \frac{\sqrt{2-\mu+2\sqrt{1-\mu}}}{\mu a_3}, \\
      Q_2 &= \Big( \frac{b_3}{a_3},\frac{\sqrt{2-2\sqrt{1-\mu}}}{\mu a_3}\Big),\qquad
      R_2 = \frac{\sqrt{2-\mu-2\sqrt{1-\mu}}}{\mu a_3}.
    \end{align*}
    The curve $\gamma$ touches $\partial B_{R_1}(Q_1)$ exactly when $\kappa$ attains its maximum
    and it touches $\partial B_{R_2}(Q_2)$ precisely when $\kappa$ attains its minimum. 
  \end{prop}
  \begin{proof}

    We recall $\mu=\frac{4(1-k^2)}{(2-k^2)^2}$ and hence $k^2=\frac{2}{\mu}+\frac{2\sqrt{1-\mu}}{\mu}$.
    Then, choosing $P=(P_1,P_2)$ as in Proposition \ref{prop:choice_of_P} we obtain the inequalities
    \begin{align*}
      Z(s;P)
      &\leq -1 + \frac{\max \kappa}{\sqrt{\mu}} 
      \stackrel{\eqref{eq:def_kappa_orbitlike}}{=} 
      -1 + \frac{2}{\sqrt{2-k^2}\sqrt\mu}
      = -1 + \frac{\sqrt{2+2\sqrt{1-\mu}}}{\sqrt{\mu}}
      =:-1+\rho_1,   \\
      Z(s;P)
      &\geq -1 + \frac{\min \kappa}{\sqrt{\mu}} 
      \stackrel{\eqref{eq:def_kappa_orbitlike}}{=} 
      -1 + \frac{2\sqrt{1-k^2}}{\sqrt{2-k^2}\sqrt\mu}
      = -1 + \frac{\sqrt{2-2\sqrt{1-\mu}}}{\sqrt{\mu}}
      =: -1+\rho_2.
    \end{align*}
    Hence we deduce $\gamma(\R)\subset \overline{B_{R_1}(Q_1)}\sm B_{R_2}(Q_2)$ for 
    $$
      Q_1:= (P_1,\rho_1 P_2),\quad 
      Q_2:= (P_1,\rho_2 P_2),\quad 
      R_1:= \sqrt{\rho_1^2-1}|P_2|,\quad
      R_2:= \sqrt{\rho_2^2-1}|P_2|,
    $$
    which proves the result.

\begin{proof}





























     Let $C$ be given by \eqref{eq:def_C} so that $Z(\cdot;P)$ satisfies the ODE \eqref{eq:ODE_Z}. We define
     the auxiliary function $W(s) := (Z(s;P)+1)\kappa(s)^{-1}-C$. Then we get
     \begin{align*}
       W''(s) 
       &= \frac{1}{\kappa(s)^2} \Big( \kappa(s)Z''(s;P)-2\kappa'(s)Z'(s;P)
       + (Z(s;P)+1)\big(-\kappa''(s)+2\frac{\kappa'(s)^2}{\kappa(s)}\big) \Big) \\
       &\stackrel{\eqref{eq:ODE_Z}}{=} \frac{1}{\kappa(s)^2} \Big( 
       (Z(s;P)+1)\big(-\kappa(s)-\kappa''(s)+2\frac{\kappa'(s)^2}{\kappa(s)} \big)
       +2\mu C\Big) \\
       &\stackrel{\eqref{eq:ODE_kappa}}{=} -\frac{2\mu}{\kappa(s)^2} \Big(
       \frac{Z(s;P)+1}{\kappa(s)}-C\Big) \\
       &= -\frac{2\mu}{\kappa(s)^2}W(s).
     \end{align*}
     By Proposition \ref{prop:W1W2_orbitlike} we can find $A,B\in\R$ such that $W(s)=AW_1(s)+BW_2(s)$ and
     thus
    \begin{align*}
      Z(s;P)
      = -1  + \kappa(s)\big(W(s)+C\big)  
      = -1  + \kappa(s)\big( AW_1(s) + B W_2(s) + C\big)
    \end{align*}
    so that \eqref{eq:formula_Z} is proved. Solving this identity for $W_1,W_2$ and differentiating it with
    respect to~$s$ we get the following equations for $A,B$:
     \begin{align*}
      \matII{ W_1(s_0)}{ W_2(s_0)}{ W_1'(s_0)}{ W_2'(s_0)}\vecII{A}{B}
      = \vecII{\frac{Z(s_0;P)+1}{\kappa(s_0)}-C}{\big(\frac{Z(\cdot;P)+1}{\kappa}-C\big)'(s_0)} 
      =  \vecII{\frac{Z(s_0;P)+1}{\kappa(s_0)}-C}{\frac{Z'(s_0;P)}{\kappa(s_0)}-
        \frac{\kappa'(s_0)(Z(s_0;P)+1)}{\kappa(s_0)^2}}.  
    \end{align*}
    Plugging in the formulas for $Z(s_0;P),Z'(s_0;P)$ and $C$, see
    \eqref{eq:def_Z},\eqref{eq:formula_Zprime},\eqref{eq:def_C}.  





















   \end{proof}

   So for any given elastica $\gamma:\R\to\Hh$  the equations \eqref{eq:formula_Z},\eqref{eq:formula_AB}
   hold for all $s,s_0\in\R$ and all $P\in \R^2,P_2\neq 0$. Hence, we may derive explicit formulas for
   orbitlike elasticae \r{$(\gamma_1,\gamma_2)$} by equating the coefficients on each side of
   \eqref{eq:formula_Z}.

The angular progress $\vartheta$ of a wavelike elastica can again be measured by evaluating an integral
  depending only on the curvature. By Proposition~\ref{prop:W1W2_wavelike}~(i)
  and~\eqref{eq:def_Wj_wavelike} there is a smooth function $\vartheta$ such that
  \begin{align} \label{eq:def_theta_wavelike}
      \hat W_2(s)-i\hat W_1(s) = \sqrt{\kappa(s)^2-\mu} \big( \cosh(\vartheta(s))+i
      \sinh(\vartheta(s)) \big).
  \end{align} 
  Again $\vartheta$ is thus defined only up to additive multiples of $2\pi$ so that we may require $\vartheta$
  to satisfy the inequality $-2\pi<\vartheta(-s_*)\leq 0$. In section~\ref{subsec:proof_propositions_wavelike}
  we will derive the following properties of $\vartheta$.

\begin{proof}
    Let $P=(P_1,P_2)$ be given as in Proposition \ref{prop:choice_of_P_wavelike}. By definition
    of $Z(\cdot;P)$ and $P_2^2=-|P_2|^2$ we find
    $(\gamma_1-P_1)^2+\gamma_2^2-|P_2|^2=2\gamma_2|P_2|\frac{\kappa}{\sqrt{|\mu|}}$ and thus
    \begin{align*}
      (\gamma_1-P_1)^2+(\gamma_2+\rho|P_2|)^2 &\geq |P_2|^2(1+\rho^2), \\
      (\gamma_1-P_1)^2+(\gamma_2-\rho|P_2|)^2 &\leq |P_2|^2(1+\rho^2),\\
      \text{where }\quad
      \rho:= \frac{\max |\kappa|}{\sqrt{|\mu|}}
      &= \frac{2k}{\sqrt{2k^2-1}\sqrt{|\mu|}} = \frac{\sqrt{2+2\sqrt{1-\mu}}}{\sqrt{|\mu|}}.
    \end{align*}
    Here equality holds if and only if $\kappa$ attains its minimum/maximum, respectively. 
    So if we set
    $$
      Q_1:=(P_1,\rho|P_2|),\quad Q_2:=(P_1,-\rho|P_2|),\quad R_1:=R_2:=|P_2|\sqrt{1+\rho^2}
    $$
    then $\gamma(\R)\subset \overline{B_{R_1}(Q_1)}\sm B_{R_2}(Q_2)$, which is the first statement of the
    theorem. From the explicit formulas from Theorem \ref{thm:explicit_formula_wavelike} and
    Proposition~\ref{prop:W1W2_wavelike} we infer $\gamma_2(s) \to  0$ as $s\to \pm\infty$ and 
    \begin{align*}
      \lim_{s\to\pm\infty}
      \gamma_1(s) 
       \stackrel{\eqref{eq:explicit_formula_wavelike}}{=} 
        \lim_{s\to\pm\infty} \frac{b_1 \frac{\hat W_1(s)}{\hat W_2(s)}+b_2+b_3 \frac{\kappa(s)}{\hat W_2(s)}
         }{a_1    \frac{\hat W_1(s)}{\hat W_2(s)}+a_2+a_3 \frac{\kappa(s)}{\hat W_2(s)}} 
         = \frac{\mp b_1 +b_2}{\mp a_1 +a_2} 
       \stackrel{\eqref{eq:wavelike_a_1a_2a_3b_1b_2b_3}}{=} 
         \frac{b_3}{a_3} \pm \frac{1}{\sqrt{|\mu|} a_3}.
    \end{align*}
  \end{proof} 

  So we conclude as in \cite{LanSing_the_total} that wavelike elasticae with
  $a_3\neq 0$ oscillate around the halfcircle around $(b_3/a_3,0)$ with radius
  $1/(\sqrt{|\mu|}a_3)$. As we show now, a somewhat similar phenomenon occurs in the case $a_3=0$ . Here, 
  $\gamma$ is an unbounded curve lying inside a cone with apex  $(b_1/a_1,0)$ and opening angle
  $2\arctan( \sqrt{2+2\sqrt{1-\mu}}/\sqrt{|\mu|})$ and it oscillates around the vertical axis of the cone,
  see Figure~\ref{Fig:orbitlike_oscillations} or Fig.~3 in the Eichmann's paper \cite{Eich_nonuniqueness}
  where the same phenomenon has been observed. The precise statement for the case $a_3=0$ is the following:

\begin{proof}
    The conditions~\eqref{eq:wavelike_a_1a_2a_3b_1b_2b_3} from Theorem~\ref{thm:explicit_formula_wavelike}
    imply 
    $$
      \gamma_1(s)
      = \frac{b_1(\hat W_1(s)+\sign(a_1) \hat W_2(s))+b_3 \kappa(s)}{a_1 \hat W_1(s)+|a_1| \hat W_2(s)}

      = \frac{b_1}{a_1} + \frac{\sign(b_3)\kappa(s) \gamma_2(s)}{\sqrt{|\mu|}}.
    $$
    This identity and 
    $$
      - \min_\R \kappa = \max_\R \kappa = \frac{2k}{\sqrt{2k^2-1}} = \sqrt{2+2\sqrt{1-\mu}}
    $$
    proves the first two assertions. Additionally, Proposition~\ref{prop:W1W2_wavelike} implies $\hat
    W_2(s)\to\infty$ as $s\to\pm\infty$ so that the claim follows from 
    $$
      \gamma_2(s)\hat W_2(s) 
      = \frac{\hat W_2(s)}{a_1\hat W_1(s)+|a_1|\hat W_2(s)}
      \to \frac{1}{\mp a_1+|a_1|} \quad\text{as }s\to\pm\infty. 
    $$ 
  \end{proof}


